    if (!['http:', 'https:'].includes(u.protocol)) return res.status(400).send('bad scheme');
    const { address } = await dns.lookup(u.hostname);
    if (!net.isIPv4(address) || isPrivate(address)) return res.status(400).send('blocked');
    const r = await axios.get(u.toString(), { timeout: 5000, maxRedirects: 0 });
    res.status(r.status).send(typeof r.data === 'string' ? r.data : JSON.stringify(r.data));
  } catch (e) {
    res.status(502).send(String(e));
  }
});

